  duration: Schema.optional(Schema.NullOr(Schema.Number.check(Schema.isGreaterThanOrEqualTo(0)))),
  user: Schema.optional(Schema.NullOr(Schema.Struct({ id: ID, username: Schema.NonEmptyString }))),
})
